import logging
from taf.trafficgenerator.iperf.host import IperfLocalHost, IperfRemoteHost
from taf.trafficgenerator.iperf.traffic_generator import IperfServerTrafficGenerator, IperfClientTrafficGenerator
from taf.trafficgenerator.iperf.options import (Iperf2ServerOptions, Iperf2ClientOptions,
                                                Iperf3ServerOptions, Iperf3ClientOptions)
from taf.trafficgenerator.iperf.command import (WindowsIperfCommands, LinuxIperfCommands, LocalAdbIperfCommands,
                                                RemoteAdbIperfCommands)
from taf.trafficgenerator.iperf.temporary_log import DefaultWindowsTemporaryLog, DefaultLinuxTemporaryLog
from taf.trafficgenerator.iperf.exceptions import MandatoryParameterNotProvided


class IperfHostFactory(object):

    _HOST_NAME = 'host_{}_{}_{}'

    def __init__(self, logger=None):
        self._logger = logger or logging

    def create(self, host_configuration=None):
        if host_configuration:
            return self._create_remote_host(host_configuration)
        else:
            return IperfLocalHost(self._logger)

    def _create_remote_host(self, host_configuration):
        required_kwargs = {'host', 'username', 'password'}
        required_kwargs_result = required_kwargs.difference(host_configuration.keys())
        if required_kwargs_result:
            raise MandatoryParameterNotProvided('Missing parameters: {}'.format(required_kwargs_result))
        host = host_configuration['host']
        username = host_configuration['username']
        password = host_configuration['password']
        port = host_configuration.get('port', 22)
        proxy_host = host_configuration.get('proxy_host')
        proxy_port = host_configuration.get('proxy_port', 22)
        proxy_username = host_configuration.get('proxy_username')
        proxy_password = host_configuration.get('proxy_password')

        if not proxy_host:
            self._logger.info('Create iperf host "{}"'.format(self._HOST_NAME.format(host, port, username)))
        else:
            self._logger.info('Create iperf host "{}" with proxy "{}"'.format(
                self._HOST_NAME.format(host, port, username),
                self._HOST_NAME.format(proxy_host, proxy_port, proxy_username)))
        return IperfRemoteHost(host, username, password, port,
                               proxy_host=proxy_host,
                               proxy_port=proxy_port,
                               proxy_username=proxy_username,
                               proxy_password=proxy_password,
                               logger=self._logger)


def _create_commands(host, cmd_options, logger):

    if host.is_windows():
        default_temporary_log = DefaultWindowsTemporaryLog()
    else:
        default_temporary_log = DefaultLinuxTemporaryLog()

    if host.builtin_iperf_commands_constructor:
        return host.builtin_iperf_commands_constructor(cmd_options, host, default_temporary_log)

    if cmd_options.adb_shell:
        if host.remote:
            commands = RemoteAdbIperfCommands(cmd_options, host, default_temporary_log, logger)
        else:
            commands = LocalAdbIperfCommands(cmd_options, host, default_temporary_log, logger)

    elif host.is_windows():
        commands = WindowsIperfCommands(cmd_options, host, default_temporary_log, logger)
    else:
        commands = LinuxIperfCommands(cmd_options, host, default_temporary_log, logger)
    return commands


class IperfFactory(object):

    def __init__(self, logger=None):
        self._logger = logger or logging

    def create(self, host, cmd_options, log_path=None):
        commands = _create_commands(host, cmd_options, self._logger)
        if cmd_options.is_server_options():
            return IperfServerTrafficGenerator(host, commands, log_path, self._logger)
        else:
            return IperfClientTrafficGenerator(host, commands, log_path, self._logger)


class Iperf2ServerOptionsFactory(object):

    def __init__(self, logger=None):
        self._logger = logger or logging
        super(Iperf2ServerOptionsFactory, self).__init__()

    def create(self, iperf_path, cmd_options, adb=None, serial_number=None):
        self._logger.info('create iperf server command options {}'.format(cmd_options))
        return Iperf2ServerOptions(iperf_path, cmd_options, adb=adb, serial_number=serial_number)


